    const rdSym = { read: '\u2713 Read and analysed', reading: '\u25d0 Reading', unread: '\u25cb Not started' }[it.read || 'unread']; const cName = (L.COLLECTIONS.find((c) => c[0] === it.coll) || [0, it.coll])[1];
    return '<div class="gs-item rd-' + (it.read || 'unread') + ' co-' + esc(it.coll) + '"><div class="gs-spread"><div style="flex:1;min-width:260px"><span class="gs-rdchip rd-' + (it.read || 'unread') + '">' + rdSym + '</span> <span class="gs-cochip co-' + esc(it.coll) + '">' + esc(cName) + '</span><br><b>' + esc(it.title) + '</b><div class="gs-note">' + esc((it.authors || []).slice(0, 5).join(', ') + ((it.authors || []).length > 5 ? ', et al.' : '')) + ' · ' + esc(it.year) + ' · ' + esc(it.journal) + '</div><div class="gs-row" style="margin-top:4px"><button class="gs-chipbtn" data-act="lab:copykey" data-id="' + it.id + '" title="Copy the citation to paste into your writing">[@' + esc(it.key) + ']</button><span class="gs-chip ' + k.cls + '">' + esc(k.label) + '</span>' + (it.doi ? '<a class="gs-chip cy" target="_blank" rel="noopener" href="https://doi.org/' + esc(it.doi) + '">DOI</a>' : '<span class="gs-chip warn">no DOI</span>') + (it.pmid ? '<a class="gs-chip cy" target="_blank" rel="noopener" href="https://pubmed.ncbi.nlm.nih.gov/' + esc(it.pmid) + '/">PubMed</a>' : '') + (it.oaUrl ? '<a class="gs-chip ok" target="_blank" rel="noopener" href="' + esc(it.oaUrl) + '">Open access copy</a>' : '') + (it.cited ? '<span class="gs-chip">cited ' + it.cited + '×</span>' : '') + '</div></div><div class="gs-row"><select class="gs-sel gs-sm" style="width:auto" data-bind="library.items.' + i + '.coll" aria-label="Collection">' + L.COLLECTIONS.map((c) => '<option value="' + c[0] + '"' + (it.coll === c[0] ? ' selected' : '') + '>' + c[1] + '</option>').join('') + '</select><select class="gs-sel gs-sm" style="width:auto" data-bind="library.items.' + i + '.read" aria-label="Reading status">' + READ.map((c) => '<option value="' + c[0] + '"' + (it.read === c[0] ? ' selected' : '') + '>' + c[1] + '</option>').join('') + '</select></div></div>' +
      '<div class="gs-row" style="margin-top:6px"><button class="gs-btn3 gs-sm" data-act="lab:toggle" data-id="' + it.id + '">' + (open ? 'Hide details' : 'Abstract, tags, notes, full text') + '</button><button class="gs-btn3 gs-sm" data-act="lab:read" data-id="' + it.id + '">Read and analyse</button><button class="gs-btn3 gs-sm gs-danger" data-act="lab:remove" data-id="' + it.id + '">Remove</button></div>' +
      (open ? '<div class="gs-itembody">' + abs + '<label class="gs-f" for="tg-' + it.id + '">Tags (comma separated)</label><input class="gs-in" id="tg-' + it.id + '" data-lab="tags" data-id="' + it.id + '" value="' + esc((it.tags || []).join(', ')) + '"><label class="gs-f" for="nt-' + it.id + '">Notes: why is this paper in my library?</label><textarea class="gs-ta" id="nt-' + it.id + '" style="min-height:70px" data-bind="library.items.' + i + '.notes">' + esc(it.notes) + '</textarea>' + paperLinks(it) + '<label class="gs-f" for="ft-' + it.id + '">Where is the full text?</label><select class="gs-sel gs-sm" style="width:auto" id="ft-' + it.id + '" data-bind="library.items.' + i + '.fulltext">' + FT.map((c) => '<option value="' + c[0] + '"' + ((it.fulltext || 'none') === c[0] ? ' selected' : '') + '>' + c[1] + '</option>').join('') + '</select><p class="gs-note">The library page names its interlibrary services and AskUs@uwp.edu. It does not state a request form or turnaround time, so ask them. <a target="_blank" rel="noopener" href="' + L.LIBRARY.ill + '">Resource and interlibrary services</a> · <a target="_blank" rel="noopener" href="' + L.LIBRARY.databases + '">Databases A to Z</a></p></div>' : '') + '</div>';
